git-tree-commit-id.solution:
import hashlib

def _oid(kind, body):
    data = body.encode("utf-8")
    return hashlib.sha1(("%s %d" % (kind, len(data))).encode() + b"\0" + data).hexdigest()

def commit_id(entries, parents, author, message):
    rows = sorted(entries, key=lambda e: e[1])
    tree_body = "".join("%s %s\t%s\n" % (m, n, o) for m, n, o in rows)
    tree = _oid("tree", tree_body)
    body = "tree %s\n" % tree
    for p in parents:
        body += "parent %s\n" % p
    body += "author %s\n\n%s\n" % (author, message)
    return [tree, _oid("commit", body)]

git-abbreviate-ids.solution:
def abbreviate(ids, min_len):
    order = sorted(range(len(ids)), key=lambda i: ids[i])
    def common(a, b):
        n = 0
        for x, y in zip(a, b):
            if x != y:
                break
            n += 1
        return n
    need = [min_len] * len(ids)
    for k in range(len(order) - 1):
        i, j = order[k], order[k + 1]
        c = common(ids[i], ids[j]) + 1
        if c > need[i]:
            need[i] = c
        if c > need[j]:
            need[j] = c
    return [ids[i][:need[i]] for i in range(len(ids))]

git-gitignore-match.solution:
import re

def _seg(seg, name):
    rx = ""
    for ch in seg:
        if ch == "*":
            rx += "[^/]*"
        elif ch == "?":
            rx += "[^/]"
        else:
            rx += re.escape(ch)
    return re.fullmatch(rx, name) is not None

def _match(psegs, parts):
    if not psegs:
        return not parts
    if psegs[0] == "**":
        return any(_match(psegs[1:], parts[k:]) for k in range(len(parts) + 1))
    if not parts:
        return False
    return _seg(psegs[0], parts[0]) and _match(psegs[1:], parts[1:])

def is_ignored(patterns, path):
    parts = path.split("/")
    ignored = False
    for raw in patterns:
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        neg = line.startswith("!")
        if neg:
            line = line[1:]
        dir_only = line.endswith("/")
        if dir_only:
            line = line[:-1]
        anchored = "/" in line
        if line.startswith("/"):
            line = line[1:]
        psegs = line.split("/")
        if not anchored:
            psegs = ["**"] + psegs
        hit = False
        for k in range(1, len(parts) + 1):
            if k == len(parts) and dir_only:
                continue
            if _match(psegs, parts[:k]):
                hit = True
                break
        if hit:
            ignored = not neg
    return ignored

git-conventional-commit.solution:
import re

_TYPES = "feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert"
_RX = re.compile(r"(" + _TYPES + r")(?:\(([a-z0-9-]+)\))?(!)?: (.+)")

def parse_commit(message):
    lines = message.split("\n")
    header = lines[0]
    if len(header) > 72:
        return None
    m = _RX.fullmatch(header)
    if not m:
        return None
    desc = m.group(4)
    if desc.startswith(" ") or desc.endswith("."):
        return None
    if len(lines) > 1 and lines[1] != "":
        return None
    breaking = m.group(3) is not None
    for line in lines[1:]:
        if line.startswith("BREAKING CHANGE: ") or line.startswith("BREAKING-CHANGE: "):
            breaking = True
    return {"type": m.group(1), "scope": m.group(2), "description": desc, "breaking": breaking}

git-sort-version-tags.solution:
import re

_RX = re.compile(r"v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?")

def sort_tags(tags):
    keyed = []
    for t in tags:
        m = _RX.fullmatch(t)
        if not m:
            continue
        core = (int(m.group(1)), int(m.group(2)), int(m.group(3)))
        pre = m.group(4)
        if pre is None:
            pk = (1, ())
        else:
            ids = []
            for part in pre.split("."):
                if part.isdigit():
                    ids.append((0, int(part), ""))
                else:
                    ids.append((1, 0, part))
            pk = (0, tuple(ids))
        keyed.append(((core, pk), t))
    keyed.sort(key=lambda kv: kv[0])
    return [t for _, t in keyed]

git-parse-refspec.solution:
def parse_refspec(spec):
    if any(ch.isspace() for ch in spec):
        return None
    force = spec.startswith("+")
    if force:
        spec = spec[1:]
    if spec.count(":") > 1:
        return None
    if ":" in spec:
        src, dst = spec.split(":")
        if dst == "":
            return None
    else:
        src, dst = spec, None
        if src == "":
            return None
    if src.count("*") > 1 or (dst is not None and dst.count("*") > 1):
        return None
    if dst is None:
        if "*" in src:
            return None
        pattern = False
    else:
        if ("*" in src) != ("*" in dst):
            return None
        pattern = "*" in dst
    return {"force": force, "src": src, "dst": dst, "pattern": pattern}

git-is-ancestor.solution:
def can_fast_forward(parents, current, target):
    seen = {target}
    stack = [target]
    while stack:
        c = stack.pop()
        if c == current:
            return True
        for p in parents.get(c, []):
            if p not in seen:
                seen.add(p)
                stack.append(p)
    return False

