        c = stack.pop()
        for p in parents.get(c, []):
            if p not in seen:
                seen.add(p)
                stack.append(p)
    return seen

def merge_base(parents, a, b):
    common = _anc(parents, a) & _anc(parents, b)
    dominated = set()
    for c in common:
        dominated.update(parents.get(c, []))
    return sorted(common - dominated)

