git-log-order.solution:
import heapq

def log_order(commits, start):
    seen = {start}
    stack = [start]
    while stack:
        c = stack.pop()
        for p in commits[c]["parents"]:
            if p not in seen:
                seen.add(p)
                stack.append(p)
    pending = {c: 0 for c in seen}
    for c in seen:
        for p in commits[c]["parents"]:
            pending[p] += 1
    heap = [(-commits[start]["date"], start)]
    out = []
    while heap:
        _, c = heapq.heappop(heap)
        out.append(c)
        for p in commits[c]["parents"]:
            pending[p] -= 1
            if pending[p] == 0:
                heapq.heappush(heap, (-commits[p]["date"], p))
    return out

git-resolve-revision.solution:
import re

def resolve(parents, refs, expr):
    m = re.fullmatch(r"([^~^]+)((?:[~^][0-9]*)*)", expr)
    if not m:
        return None
    cur = refs.get(m.group(1), m.group(1))
    if cur not in parents:
        return None
    for op, num in re.findall(r"([~^])([0-9]*)", m.group(2)):
        n = int(num) if num else 1
        if op == "~":
            for _ in range(n):
                if not parents[cur]:
                    return None
                cur = parents[cur][0]
        elif n > 0:
            if n > len(parents[cur]):
                return None
            cur = parents[cur][n - 1]
    return cur

git-bisect-next.solution:
def _anc(parents, x):
    seen = {x}
    stack = [x]
    while stack:
        c = stack.pop()
        for p in parents.get(c, []):
            if p not in seen:
                seen.add(p)
                stack.append(p)
    return seen

def bisect_next(parents, good, bad):
    cleared = set()
    for g in good:
        cleared |= _anc(parents, g)
    suspects = _anc(parents, bad) - cleared
    n = len(suspects)
    if n == 0:
        return None
    best = None
    for c in sorted(suspects):
        x = len(_anc(parents, c) & suspects)
        score = min(x, n - x)
        if best is None or score > best[0]:
            best = (score, c)
    return best[1]

git-push-check.solution:
def push_check(parents, remote_tip, local_tip, force):
    if remote_tip is None:
        return "new-branch"
    if remote_tip == local_tip:
        return "up-to-date"
    seen = {local_tip}
    stack = [local_tip]
    while stack:
        c = stack.pop()
        if c == remote_tip:
            return "fast-forward"
        for p in parents.get(c, []):
            if p not in seen:
                seen.add(p)
                stack.append(p)
    return "forced" if force else "rejected"

