def recover_branch(entries, start_branch, branch):
    current = start_branch
    last = None
    prefix = "checkout: moving from "
    for sha, msg in entries:
        if msg.startswith(prefix):
            current = msg.rsplit(" to ", 1)[1]
        if current == branch:
            last = sha
    return last

git-lcs-diff.solution:
def _table(a, b):
    n, m = len(a), len(b)
    L = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                L[i][j] = L[i + 1][j + 1] + 1
            else:
                L[i][j] = max(L[i + 1][j], L[i][j + 1])
    return L

def line_diff(a, b):
    L = _table(a, b)
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            out.append("  " + a[i])
            i += 1
            j += 1
        elif L[i + 1][j] >= L[i][j + 1]:
            out.append("- " + a[i])
            i += 1
        else:
            out.append("+ " + b[j])
            j += 1
    out.extend("- " + x for x in a[i:])
    out.extend("+ " + x for x in b[j:])
    return out

git-apply-hunk.solution:
import re

def apply_hunk(lines, hunk):
    if not hunk:
        return None
    m = re.match(r"@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@", hunk[0])
    if not m:
        return None
    start = int(m.group(1))
    old_n = int(m.group(2)) if m.group(2) is not None else 1
    new_n = int(m.group(4)) if m.group(4) is not None else 1
    old, new = [], []
    for row in hunk[1:]:
        tag = row[:1]
        if tag == " ":
            old.append(row[1:])
            new.append(row[1:])
        elif tag == "-":
            old.append(row[1:])
        elif tag == "+":
            new.append(row[1:])
        else:
            return None
    if len(old) != old_n or len(new) != new_n:
        return None
    pos = start if old_n == 0 else start - 1
    if pos < 0 or pos + old_n > len(lines):
        return None
    if lines[pos:pos + old_n] != old:
        return None
    return lines[:pos] + new + lines[pos + old_n:]

git-three-way-merge.solution:
def _table(a, b):
    n, m = len(a), len(b)
    L = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                L[i][j] = L[i + 1][j + 1] + 1
            else:
                L[i][j] = max(L[i + 1][j], L[i][j + 1])
    return L

def _pairs(a, b):
    L = _table(a, b)
    i = j = 0
    out = {}
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            out[i] = j
            i += 1
            j += 1
        elif L[i + 1][j] >= L[i][j + 1]:
            i += 1
        else:
            j += 1
    return out

def merge3(base, ours, theirs):
    mo = _pairs(base, ours)
    mt = _pairs(base, theirs)
    out = []
    conflicts = 0
    pb = po = pt = 0
    anchors = [i for i in range(len(base)) if i in mo and i in mt]
    anchors.append(None)
    for i in anchors:
        if i is None:
            B, O, T = base[pb:], ours[po:], theirs[pt:]
        else:
            B, O, T = base[pb:i], ours[po:mo[i]], theirs[pt:mt[i]]
        if O == T:
            out.extend(O)
        elif O == B:
            out.extend(T)
        elif T == B:
            out.extend(O)
        else:
            conflicts += 1
            out.append("<<<<<<< ours")
            out.extend(O)
            out.append("=======")
            out.extend(T)
            out.append(">>>>>>> theirs")
        if i is not None:
            out.append(base[i])
            pb, po, pt = i + 1, mo[i] + 1, mt[i] + 1
    return [out, conflicts]

git-cherry-pick-conflicts.solution:
def cherry_pick_conflicts(source, picked, target_paths):
    hot = set(target_paths)
    want = set(picked)
    out = []
    for cid, paths in source:
        if cid in want:
            clash = sorted(set(paths) & hot)
            if clash:
                out.append([cid, clash])
        else:
            hot.update(paths)
    return out

git-rebase-todo.solution:
def apply_todo(commits, todo):
    msg = {c[0]: c[1] for c in commits}
    used = set()
    out = []
    for step in todo:
        action, cid = step[0], step[1]
        if cid not in msg or cid in used:
            return None
        used.add(cid)
        if action == "pick":
            out.append([[cid], msg[cid]])
        elif action == "reword":
            out.append([[cid], step[2]])
        elif action in ("squash", "fixup"):
            if not out:
                return None
            out[-1][0].append(cid)
            if action == "squash":
                out[-1][1] += "\n\n" + msg[cid]
        elif action != "drop":
            return None
    return out

git-squash-commits.solution:
def squash(base, commits):
    if not commits:
        return None
    final = dict(base)
    for _, changes in commits:
        for path, content in changes.items():
            if content is None:
                final.pop(path, None)
            else:
                final[path] = content
    net = {}
    for path in set(base) | set(final):
        if base.get(path) != final.get(path):
            net[path] = final.get(path)
    message = commits[0][0]
    if len(commits) > 1:
        message += "\n\n" + "\n".join("* " + m for m, _ in commits[1:])
    return [message, net]

git-reset-modes.solution:
def reset(commits, head, index, worktree, mode, target):
    if target not in commits or mode not in ("soft", "mixed", "hard"):
        return None
    snap = commits[target]
    if mode == "soft":
        return [target, dict(index), dict(worktree)]
    if mode == "mixed":
        return [target, dict(snap), dict(worktree)]
    new_wt = dict(snap)
    for path, content in worktree.items():
        if path not in index and path not in snap:
            new_wt[path] = content
    return [target, dict(snap), new_wt]

git-status-categories.solution:
def status(head, index, worktree):
    staged, unstaged, untracked = [], [], []
    for p in sorted(set(head) | set(index)):
        if p not in head:
            staged.append("new file: " + p)
        elif p not in index:
            staged.append("deleted: " + p)
        elif head[p] != index[p]:
            staged.append("modified: " + p)
    for p in sorted(index):
        if p not in worktree:
            unstaged.append("deleted: " + p)
        elif worktree[p] != index[p]:
            unstaged.append("modified: " + p)
    for p in sorted(worktree):
        if p not in index:
            untracked.append(p)
    return {"staged": staged, "unstaged": unstaged, "untracked": untracked}

git-staging-sim.solution:
def simulate(ops):
    head, index, wt = {}, {}, {}
    count = 0

    def stage(p):
        if p in wt:
            index[p] = wt[p]
        else:
            index.pop(p, None)

    for op in ops:
        kind = op[0]
        if kind == "write":
            wt[op[1]] = op[2]
        elif kind == "remove":
            wt.pop(op[1], None)
        elif kind == "add":
            if op[1] == ".":
                for p in set(wt) | set(index):
                    stage(p)
            else:
                stage(op[1])
        elif kind == "unstage":
            if op[1] in head:
                index[op[1]] = head[op[1]]
            else:
                index.pop(op[1], None)
        elif kind == "commit":
            if index != head:
                head = dict(index)
                count += 1
    lines = []
    for p in sorted(set(head) | set(index) | set(wt)):
        x = y = " "
        if p in index and p not in head:
            x = "A"
        elif p in head and p not in index:
            x = "D"
        elif p in head and head[p] != index[p]:
            x = "M"
        if p in index:
            if p not in wt:
                y = "D"
            elif wt[p] != index[p]:
                y = "M"
        if x != " " or y != " ":
            lines.append(x + y + " " + p)
        if p in wt and p not in index:
            lines.append("?? " + p)
    return [count, lines]

git-stash-stack.solution:
def stash_sim(ops):
    dirty = {}
    stack = []
    errors = []
    for op in ops:
        kind = op[0]
        if kind == "edit":
            dirty[op[1]] = op[2]
        elif kind == "push":
            if not dirty:
                errors.append("nothing to stash")
            else:
                stack.insert(0, (op[1], dirty))
                dirty = {}
        elif kind in ("apply", "pop"):
            n = op[1]
            if n >= len(stack):
                errors.append("no such stash")
                continue
            saved = stack[n][1]
            if any(p in dirty for p in saved):
                errors.append("conflict")
                continue
            dirty.update(saved)
            if kind == "pop":
                del stack[n]
        elif kind == "drop":
            if op[1] >= len(stack):
                errors.append("no such stash")
            else:
                del stack[op[1]]
    listing = ["stash@{%d}: %s" % (i, m) for i, (m, _) in enumerate(stack)]
    return [dirty, listing, errors]
